    // Main method that dispatches to the appropriate quarter-circle method
    public static void checkReachability(Direction direction) throws GameActionException {
        switch (direction) {

        case Direction.NORTH:
            checkReachabilityN();
            break;
        
        case Direction.EAST:
            checkReachabilityE();
            break;
        
        case Direction.SOUTH:
            checkReachabilityS();
            break;
        
        case Direction.WEST:
            checkReachabilityW();
            break;
        
        case Direction.NORTHEAST:
            checkReachabilityNE();
            break;
        
        case Direction.SOUTHEAST:
            checkReachabilitySE();
            break;
        
        case Direction.NORTHWEST:
            checkReachabilityNW();
            break;
        
        case Direction.SOUTHWEST:
            checkReachabilitySW();
            break;
        
            default:
                throw new IllegalArgumentException("Invalid direction: " + direction);
        }
    }
